const FIREBASE_MESSAGING_SW_PATH =
  '/firebase-messaging-sw.js';

const FIREBASE_WEB_PUSH_VAPID_KEY =
  'BIqMt2i7vb28AEucSAbRyjywLcOVAaDvV2ZTSAr2qVJfbHUI6zZNaZnnz3F8TeCb_CwctlcBvfzk_Jn0x2EOZl4';

let foregroundMessageHandlerRegistered = false;

function getPublicAssetUrl(assetPath: string): string {
  const normalizedAssetPath = assetPath.startsWith('/')
    ? assetPath
    : `/${assetPath}`;

  const manifestHref =
    document.querySelector<HTMLLinkElement>(
      'link[rel="manifest"]'
    )?.href;

  if (!manifestHref) {
    return normalizedAssetPath;
  }

  return new URL(
    `.${normalizedAssetPath}`,
    manifestHref
  ).pathname;
}

async function salvarStatusNotificacao(
  usuario: User,
  status: string,
  detalhes?: string
) {
  await setDoc(
    doc(firestore, 'usuarios', usuario.uid),
    {
      notificacoesWebStatus: status,
      notificacoesWebDetalhes: detalhes || null,
      notificacoesWebAtualizadoEm: serverTimestamp(),
    },
    { merge: true }
  );
}

async function getReadyServiceWorkerRegistration():
  Promise<ServiceWorkerRegistration> {
  const swUrl = getPublicAssetUrl(
    FIREBASE_MESSAGING_SW_PATH
  );

  const swScope = new URL(
    '.',
    new URL(swUrl, window.location.origin)
  ).href;

  const existingRegistration =
    await navigator.serviceWorker.getRegistration(
      swScope
    );

  const registration =
    existingRegistration ||
    await navigator.serviceWorker.register(
      swUrl,
      {
        scope: new URL(swScope).pathname,
      }
    );

  await registration.update().catch(error => {
    console.log(
      'Não foi possível atualizar o Service Worker:',
      error
    );
  });

  /*
   * Aguarda o Service Worker usado pelo Firebase
   * ficar completamente ativo.
   */
  if (!registration.active) {
    await new Promise<void>(resolve => {
      const worker =
        registration.installing ||
        registration.waiting;

      if (!worker) {
        resolve();
        return;
      }

      const verificarEstado = () => {
        if (worker.state === 'activated') {
          worker.removeEventListener(
            'statechange',
            verificarEstado
          );

          resolve();
        }
      };

      worker.addEventListener(
        'statechange',
        verificarEstado
      );

      verificarEstado();
    });
  }

  return registration;
}

/*
 * Exibe mensagens recebidas enquanto o aplicativo está aberto.
 *
 * No Chrome para Android, utilizar showNotification pelo
 * Service Worker é mais confiável que new Notification().
 */
async function showForegroundNotification(
  payload: MessagePayload
): Promise<void> {
  if (
    typeof window === 'undefined' ||
    typeof document === 'undefined' ||
    document.visibilityState !== 'visible' ||
    Notification.permission !== 'granted'
  ) {
    return;
  }

  const title =
    payload.notification?.title ||
    payload.data?.title ||
    'WorshipApp';

  const body =
    payload.notification?.body ||
    payload.data?.body ||
    '';

  const url =
    payload.data?.url ||
    payload.fcmOptions?.link ||
    window.location.href;

  try {
    const registration =
      await getReadyServiceWorkerRegistration();

    await registration.showNotification(title, {
      body,
      icon: getPublicAssetUrl('/icon-512.png'),
      badge: getPublicAssetUrl('/favicon-32.png'),
      tag:
        payload.data?.tag ||
        'worship-notification',
      data: {
        ...(payload.data || {}),
        url,
      },
    });

    console.log(
      'Notificação exibida com o aplicativo aberto:',
      title
    );
  } catch (error) {
    console.log(
      'Não foi possível exibir a notificação em primeiro plano:',
      error
    );
  }
}

function urlBase64ToUint8Array(
  base64String: string
): Uint8Array {
  const padding = '='.repeat(
    (4 - (base64String.length % 4)) % 4
  );

  const base64 = `${base64String}${padding}`
    .replace(/-/g, '+')
    .replace(/_/g, '/');

  const rawData = window.atob(base64);

  const outputArray =
    new Uint8Array(rawData.length);

  for (
    let indice = 0;
    indice < rawData.length;
    indice += 1
  ) {
    outputArray[indice] =
      rawData.charCodeAt(indice);
  }

  return outputArray;
}

function chavesSaoIguais(
  chaveAtual: ArrayBuffer | null,
  chaveEsperada: Uint8Array
): boolean {
  if (!chaveAtual) {
    return true;
  }

  const atual = new Uint8Array(chaveAtual);

  if (atual.length !== chaveEsperada.length) {
    return false;
  }

  for (
    let indice = 0;
    indice < atual.length;
    indice += 1
  ) {
    if (atual[indice] !== chaveEsperada[indice]) {
      return false;
    }
  }

  return true;
}

/*
 * Remove somente uma inscrição criada anteriormente
 * com outra chave VAPID.
 *
 * Se a inscrição atual já usa a chave correta do Firebase,
 * nenhuma modificação é feita.
 */
async function migrarInscricaoAntiga(
  swRegistration: ServiceWorkerRegistration,
  messaging: Messaging
) {
  if (!swRegistration.pushManager) {
    return;
  }

  const inscricaoAtual =
    await swRegistration.pushManager
      .getSubscription();

  if (!inscricaoAtual) {
    return;
  }

  const chaveEsperada =
    urlBase64ToUint8Array(
      FIREBASE_WEB_PUSH_VAPID_KEY
    );

  const chaveAtual =
    inscricaoAtual.options
      ?.applicationServerKey || null;

  if (
    chavesSaoIguais(
      chaveAtual,
      chaveEsperada
    )
  ) {
    return;
  }

  console.log(
    'Migrando inscrição antiga para Firebase Messaging.'
  );

  /*
   * Tenta remover o token Firebase anterior.
   * Uma falha não interrompe a migração.
   */
  await deleteToken(messaging)
    .catch(() => false);

  const inscricaoDepoisDoDelete =
    await swRegistration.pushManager
      .getSubscription();

  if (inscricaoDepoisDoDelete) {
    await inscricaoDepoisDoDelete.unsubscribe();
  }
}

export async function registerFirebaseWebPush(
  usuario: User | null
): Promise<void> {
  if (
    Platform.OS !== 'web' ||
    !usuario ||
    typeof window === 'undefined'
  ) {
    return;
  }

  if (
    !('Notification' in window) ||
    !('serviceWorker' in navigator) ||
    !('PushManager' in window)
  ) {
    await salvarStatusNotificacao(
      usuario,
      'unsupported',
      'Este navegador não suporta notificações Web Push.'
    );

    return;
  }

  try {
    /*
     * A tela do aplicativo solicita a permissão.
     * Este serviço continua somente quando a permissão
     * já estiver concedida.
     */
    if (Notification.permission !== 'granted') {
      await salvarStatusNotificacao(
        usuario,
        Notification.permission
      );

      return;
    }

    const swRegistration =
      await getReadyServiceWorkerRegistration();

    const messaging = await messagingPromise;

    if (!messaging) {
      await salvarStatusNotificacao(
        usuario,
        'unsupported',
        'Firebase Messaging não está disponível neste navegador.'
      );

      return;
    }

    /*
     * Migra automaticamente a inscrição Web Push antiga
     * caso ela utilize uma chave VAPID diferente.
     */
    await migrarInscricaoAntiga(
      swRegistration,
      messaging
    );

    const fcmToken = await getToken(messaging, {
      serviceWorkerRegistration: swRegistration,
      vapidKey: FIREBASE_WEB_PUSH_VAPID_KEY,
    });

    if (!fcmToken) {
      await salvarStatusNotificacao(
        usuario,
        'no-token',
        'A permissão foi concedida, mas o FCM não retornou um token.'
      );

      return;
    }

    await setDoc(
      doc(firestore, 'usuarios', usuario.uid),
      {
        fcmToken,
        fcmTokens: arrayUnion(fcmToken),
        notificacoesWebAtivas: true,
        notificacoesWebStatus: 'active-fcm',
        notificacoesWebDetalhes: null,
        notificacoesWebAtualizadoEm:
          serverTimestamp(),

        /*
         * Remove os dados do método Web Push antigo
         * para impedir notificações duplicadas.
         */
        webPushSubscription: deleteField(),
        webPushSubscriptions: deleteField(),
      },
      { merge: true }
    );

    if (!foregroundMessageHandlerRegistered) {
      foregroundMessageHandlerRegistered = true;

      /*
       * Recebe mensagens com o aplicativo aberto e
       * solicita a exibição ao Service Worker.
       */
      onMessage(
        messaging,
        payload => {
          void showForegroundNotification(payload);
        }
      );
    }

    console.log(
      'Firebase Messaging registrado com sucesso.'
    );
  } catch (error) {
    const mensagem =
      error instanceof Error
        ? error.message
        : 'Erro desconhecido ao registrar notificações.';

    console.log(
      'Não foi possível registrar o Firebase Cloud Messaging:',
      error
    );

    await salvarStatusNotificacao(
      usuario,
      'error',
      mensagem
    ).catch(() => undefined);
  }
}